window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[28]={"id":"028","numero":28,"titre":"Infections urinaires de la femme enceinte","objectifs":[{"id":"28-1","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les facteurs favorisant les infections urinaires gravidiques","contenu":"<p>Les <span class=\"kw-def\">infections urinaires (IU) gravidiques</span> sont l'<strong>infection <span class=\"kw-etio\">bactérienne</span> la plus fréquente au cours de la <span class=\"kw-ci\">grossesse</span></strong> et concernent <span class=\"kw-chiffre\">≈ 10 %</span> des femmes enceintes. Elles sont par définition à risque de complication (mère + fœtus), avec notamment un <span class=\"kw-alerte\">risque d'accouchement prématuré ≈ 20 %</span>, surtout en cas de PNA.</p>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Critères diagnostiques</span> identiques à la femme non enceinte.</strong> Ce qui change, c'est la <em>fréquence</em>, le <em>risque évolutif</em> (mère + fœtus), la <em>stratégie de <span class=\"kw-def\">dépistage</span></em> et la <em>place de l'<span class=\"kw-ttt\">antibiothérapie</span> probabiliste</em>.\n      </div>\n\n      <h4><span class=\"kw-def\">Facteurs de risque</span> cliniques (terrain)</h4>\n\n      <ul>\n        <li><span class=\"kw-clinique\">Uropathie organique ou fonctionnelle sous-jacente</span> (malformation, troubles mictionnels)</li>\n        <li><span class=\"kw-clinique\">ATCD d'infection urinaire</span></li>\n        <li><span class=\"kw-clinique\">Diabète sucré</span> (type 1, type 2 ou gestationnel)</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Étiopathogénie</span> — Trois grands axes</h4>\n\n      <table >\n        <thead>\n          <tr><th>Type de facteur</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Facteurs mécaniques</strong></td>\n            <td>\n              <strong>Compression vésicale :</strong> utérus gravide → mauvaise vidange + résidu post-mictionnel<br>\n              <strong>Compression et étirement des uretères :</strong> favorise un <span class=\"kw-def\">reflux vésico-urétéral</span>, notamment à droite du fait de la <span class=\"kw-clinique\">dextroposition</span> utérine au cours de la <span class=\"kw-ci\">grossesse</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs hormonaux</strong></td>\n            <td>\n              <strong>Œstrogènes :</strong> hyperhémie du trigone → favorise l'adhérence des germes sur l'urothélium<br>\n              <strong>Progestérone :</strong> inhibe le péristaltisme des voies urinaires et diminue le tonus sphinctérien urétéro-vésical → reflux et stagnation des urines\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs chimiques / périnéaux</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Alcalinisation</span></strong> des urines<br>\n              <strong><span class=\"kw-def\">Glycosurie</span> physiologique</strong> (diminution du seuil rénal de réabsorption du glucose)<br>\n              <strong>Pullulation microbienne</strong> vulvopérinéale + brièveté de l'urètre féminin\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-def\">Infection urinaire</span> · 24 — Complications de la <span class=\"kw-ci\">grossesse</span> · 23 — Grossesse normale</em></p>","frequence":0},{"id":"28-2","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les germes incriminés dans les infections urinaires gravidiques","contenu":"<p>Les germes responsables sont <strong>identiques à ceux de la femme non enceinte</strong>, dominés par les <span class=\"kw-bio\">entérobactéries d'origine digestive</span>. Le portage vaginal de <span class=\"kw-bio\">streptocoque du groupe B (SGB)</span> impose une vigilance particulière en fin de <span class=\"kw-ci\">grossesse</span>.</p>\n\n      <h4>Spectre microbiologique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Germe</th><th>Place</th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><em><span class=\"kw-etio\">Escherichia coli</span></em></strong></td>\n            <td><span class=\"kw-chiffre\">70 – 80 %</span> (germe largement dominant)</td>\n            <td>Entérobactérie commensale du tube digestif, principal pourvoyeur de <span class=\"kw-etio\">cystite</span>, PNA et colonisation gravidique.</td>\n          </tr>\n          <tr>\n            <td><strong>Autres entérobactéries</strong></td>\n            <td>Minoritaires</td>\n            <td>\n              <strong><em><span class=\"kw-etio\">Proteus mirabilis</span></em> :</strong> à connaître — produit une <span class=\"kw-clinique\">uréase</span> → alcalinisation urinaire et <span class=\"kw-alerte\">lithiase phospho-ammoniaco-magnésienne</span> ; évoquer si non-amélioration sous ATB adaptée<br>\n              <strong><em><span class=\"kw-etio\">Klebsiella pneumoniae</span></em></strong>, <em>Enterobacter</em>, <em>Citrobacter</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cocci à Gram +</strong></td>\n            <td>Plus rares</td>\n            <td>\n              <strong><em><span class=\"kw-etio\">Staphylococcus saprophyticus</span></em> :</strong> femme jeune, sexuellement active<br>\n              <strong><span class=\"kw-etio\">Streptocoque</span> du groupe B (<em>S. agalactiens</em>) :</strong> impose une <span class=\"kw-ttt\">prophylaxie per-partum</span> si retrouvé dans un <span class=\"kw-bio\">ECBU</span> (cf. <em>obj-3</em>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bactéries à risque obstétrical</strong></td>\n            <td>Exceptionnel</td>\n            <td>\n              <strong><em><span class=\"kw-etio\">Listeria monocytogenes</span></em> :</strong> à rechercher sur <span class=\"kw-bio\">hémocultures</span> en cas de <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-bio\">BU</span> faiblement positive (cf. <em>obj-9</em>) — risque de chorioamniotite, fausse couche tardive, infection néonatale\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Conséquence pratique.</strong> L'<span class=\"kw-ttt\">antibiothérapie</span> probabiliste vise <em><span class=\"kw-etio\">E. coli</span></em> en <span class=\"kw-chiffre\">première intention</span>, avec <span class=\"kw-ci\">contre-indication absolue des fluoroquinolones pendant la grossesse</span> et adaptation systématique sur <span class=\"kw-bio\">antibiogramme</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-def\">Infection urinaire</span> · 177 — Anti-<span class=\"kw-etio\">infectieux</span> · 173 — Zoonose</em></p>","frequence":0},{"id":"28-3","rang":"A","rubrique":"Définition","titre":"Colonisation urinaire gravidique : connaître la définition","contenu":"<p>La <span class=\"kw-etio\">colonisation urinaire gravidique</span> (anciennement « bactériurie asymptomatique ») est définie chez la femme enceinte par la <strong>présence d'une bactériurie significative en l'absence de tout signe clinique d'<span class=\"kw-def\">infection urinaire</span></strong>.</p>\n\n      <h4><span class=\"kw-def\">Critères diagnostiques</span></h4>\n\n      <ul>\n        <li><strong>Patiente asymptomatique</strong> (pas de SFU, pas de <span class=\"kw-clinique\">fièvre</span>, pas de douleur lombaire)</li>\n        <li><strong>2 <span class=\"kw-bio\">ECBU</span> positifs successifs à la même bactérie</strong>, avec <span class=\"kw-chiffre\">bactériurie ≥ 10⁵ UFC/mL</span></li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Épidémiologie</span> et enjeux</h4>\n\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Fréquence</strong></td>\n            <td><span class=\"kw-chiffre\">≈ 5 %</span> des grossesses (<span class=\"kw-chiffre\">2 – 10 %</span> selon les sources / collège de gynécologie)</td>\n          </tr>\n          <tr>\n            <td><strong>Risque évolutif en l'absence de traitement</strong></td>\n            <td>\n              <strong><span class=\"kw-etio\">Cystite</span> aiguë et PNA :</strong> risque évalué à <span class=\"kw-alerte\">20 – 40 %</span><br>\n              <strong>Complications fœtales :</strong> accouchement prématuré, infection néonatale\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Pourquoi cette définition compte.</strong> Hors <span class=\"kw-ci\">grossesse</span>, la bactériurie asymptomatique n'est globalement pas traitée. <strong>Chez la femme enceinte, c'est l'inverse</strong> : le risque de bascule vers PNA et de complications fœtales justifie un <span class=\"kw-def\">dépistage</span> actif et un traitement systématique (cf. <em>obj-3</em>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-def\">Infection urinaire</span> · 24 — Complications de la <span class=\"kw-ci\">grossesse</span></em></p>","frequence":0},{"id":"28-4","rang":"A","rubrique":"Prise en charge","titre":"Colonisation urinaire gravidique : connaître les principes du dépistage et du traitement","contenu":"<p>Le <span class=\"kw-def\">dépistage</span> est <strong>systématique</strong> chez toute femme enceinte, modulé selon la présence ou non de <span class=\"kw-clinique\">facteurs de risque</span>. Le traitement de la colonisation est lui aussi systématique pour prévenir la bascule vers <span class=\"kw-etio\">cystite</span>, PNA et complications fœtales.</p>\n\n      <h4>Femmes « à risque »</h4>\n\n      <ul>\n        <li><span class=\"kw-clinique\">Uropathie sous-jacente</span> organique ou fonctionnelle (malformation, troubles mictionnels)</li>\n        <li><span class=\"kw-clinique\">Diabète sucré</span> (type 1, type 2 ou gestationnel)</li>\n        <li><span class=\"kw-clinique\">ATCD de cystite aiguë récidivante</span></li>\n        <li><span class=\"kw-clinique\">ATCD d'infection ou de colonisation urinaire</span></li>\n      </ul>\n\n      <h4>Stratégie de <span class=\"kw-def\">dépistage</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Profil</th><th>Modalité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Femme enceinte sans FR</strong></td>\n            <td>\n              <strong><span class=\"kw-bio\">BU</span> mensuelle</strong> à partir du <span class=\"kw-chiffre\">4ᵉ mois</span> jusqu'à l'accouchement<br>\n              <strong><span class=\"kw-bio\">ECBU</span></strong> si BU positive (<span class=\"kw-bio\">nitrites</span> et/ou <span class=\"kw-bio\">leucocytes</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Femme enceinte « à risque »</strong></td>\n            <td>\n              <strong><span class=\"kw-bio\">ECBU</span> dès la 1ʳᵉ consultation prénatale</strong><br>\n              Puis <strong><span class=\"kw-bio\">ECBU</span> mensuel</strong> jusqu'à l'accouchement\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Principes du traitement</h4>\n\n      <ol>\n        <li><strong>Pas d'<span class=\"kw-ttt\">antibiothérapie</span> probabiliste</strong> : on attend le résultat de l'<span class=\"kw-bio\">ECBU</span> et de l'<span class=\"kw-bio\">antibiogramme</span> avant de prescrire (à la différence de la <span class=\"kw-etio\">cystite</span> aiguë gravidique)</li>\n        <li><strong><span class=\"kw-ttt\">Antibiothérapie</span> adaptée à l'<span class=\"kw-bio\">antibiogramme</span></strong>, par ordre de priorité hiérarchisé sur la tolérance et le risque de résistance (cf. <em>obj-4</em>) — durée <span class=\"kw-chiffre\">7 jours</span>, sauf <span class=\"kw-ttt\">fosfomycine-trométamol</span> en prise unique</li>\n        <li><strong><span class=\"kw-def\">Suivi</span> :</strong> <span class=\"kw-bio\">ECBU</span> de contrôle <span class=\"kw-chiffre\">8 – 10 jours après l'arrêt</span> du traitement, puis <span class=\"kw-bio\">ECBU</span> <strong>mensuel</strong> jusqu'à la fin de la <span class=\"kw-ci\">grossesse</span></li>\n      </ol>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-etio\">Streptocoque</span> B isolé dans un <span class=\"kw-bio\">ECBU</span> pendant la <span class=\"kw-ci\">grossesse</span>.</strong> Cette situation est associée à une <span class=\"kw-clinique\">colonisation vaginale</span> et impose une <span class=\"kw-ttt\">antibioprophylaxie per-partum</span> systématique (même protocole que pour le portage vaginal isolé) afin de prévenir l'infection néonatale précoce à SGB.\n      </div>\n\n      <h4><span class=\"kw-ttt\">Règles hygiéno-diététiques</span> (RHD) — associées au traitement</h4>\n\n      <ul>\n        <li>Boissons abondantes (<span class=\"kw-chiffre\">≈ 2 L/jour</span>)</li>\n        <li>Mictions fréquentes, notamment <strong>après les rapports sexuels</strong></li>\n        <li>Hygiène périnéale : essuyage <strong>d'avant en arrière</strong> après la miction</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-def\">Infection urinaire</span> · 24 — Complications de la <span class=\"kw-ci\">grossesse</span> · 177 — Anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":2},{"id":"28-5","rang":"A","rubrique":"Contenu multimédia","titre":"Connaître le traitement recommandé pour une colonisation urinaire gravidique","contenu":"<p>L'efficacité des différentes molécules est globalement <strong>similaire</strong>, avec un très faible risque d'effets indésirables. Les <strong>choix de priorités sont hiérarchisés sur la tolérance digestive et sur le risque de résistance secondaire</strong>. La durée standard est de <span class=\"kw-chiffre\">7 jours</span> sauf pour la fosfomycine-trométamol (prise unique).</p>\n\n      <h4>Ordre de choix des antibiotiques — Colonisation urinaire gravidique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Ordre</th><th>Molécule (DCI)</th><th>Posologie</th><th>Durée</th><th>CI / effets indésirables</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td><span class=\"kw-ttt\">Amoxicilline</span></td>\n            <td><span class=\"kw-chiffre\">1 g</span> × 3 / j</td>\n            <td><span class=\"kw-chiffre\">7 jours</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>2ᵉ intention</strong></td>\n            <td><span class=\"kw-ttt\">Pivmécillinam</span></td>\n            <td><span class=\"kw-chiffre\">400 mg</span> × 2 / j</td>\n            <td><span class=\"kw-chiffre\">7 jours</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>3ᵉ intention</strong></td>\n            <td><span class=\"kw-ttt\">Fosfomycine-trométamol</span></td>\n            <td><span class=\"kw-chiffre\">3 g</span></td>\n            <td><span class=\"kw-chiffre\">Prise unique</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>4ᵉ intention</strong></td>\n            <td><span class=\"kw-ttt\">Triméthoprime</span></td>\n            <td><span class=\"kw-chiffre\">300 mg</span> / j</td>\n            <td><span class=\"kw-chiffre\">7 jours</span></td>\n            <td><span class=\"kw-ci\">À éviter pendant les 2 premiers mois de grossesse</span></td>\n          </tr>\n          <tr>\n            <td><strong>5ᵉ intention</strong></td>\n            <td><span class=\"kw-ttt\">Nitrofurantoïne</span></td>\n            <td><span class=\"kw-chiffre\">100 mg</span> × 3 / j</td>\n            <td><span class=\"kw-chiffre\">7 jours</span></td>\n            <td>\n              <span class=\"kw-ci\">CI :</span> traitements itératifs ; <span class=\"kw-clinique\">clairance créatinine &lt; 40 mL/min</span> ;<br>\n              <span class=\"kw-alerte\">risque pulmonaire et hépatique</span> si durée &gt; <span class=\"kw-chiffre\">10 jours</span>\n            </td>\n          </tr>\n          <tr>\n            <td>—</td>\n            <td><span class=\"kw-ttt\">Cotrimoxazole</span></td>\n            <td>1 cp × 2 / j</td>\n            <td><span class=\"kw-chiffre\">7 jours</span></td>\n            <td>(<span class=\"kw-ci\">à éviter</span> T1)</td>\n          </tr>\n          <tr>\n            <td>—</td>\n            <td><span class=\"kw-ttt\">Amoxicilline + acide clavulanique</span></td>\n            <td><span class=\"kw-chiffre\">1 g</span> × 3 / j</td>\n            <td><span class=\"kw-chiffre\">7 jours</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td>—</td>\n            <td><span class=\"kw-ttt\">Céfixime</span></td>\n            <td><span class=\"kw-chiffre\">200 mg</span> × 2 / j</td>\n            <td><span class=\"kw-chiffre\">7 jours</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td>—</td>\n            <td><span class=\"kw-ttt\">Ciprofloxacine</span></td>\n            <td><span class=\"kw-chiffre\">500 mg</span> × 2 / j</td>\n            <td><span class=\"kw-chiffre\">7 jours</span></td>\n            <td><span class=\"kw-ci\">FQ globalement à éviter pendant la grossesse</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Logique de la hiérarchie.</strong> L'<span class=\"kw-ttt\">amoxicilline</span> est privilégiée car peu impactante sur l'écologie <span class=\"kw-etio\">bactérienne</span> et bien tolérée chez la femme enceinte. Les molécules « <span class=\"kw-ci\">à éviter</span> pendant les 2 premiers mois » (triméthoprime, <span class=\"kw-ttt\">cotrimoxazole</span>) le sont en raison du <span class=\"kw-alerte\">risque tératogène</span> théorique (antifoliques) au cours de l'organogenèse.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 177 — Anti-<span class=\"kw-etio\">infectieux</span> · 161 — <span class=\"kw-def\">Infection urinaire</span></em></p>","frequence":0},{"id":"28-6","rang":"A","rubrique":"Diagnostic clinique","titre":"Cystite aiguë gravidique : connaître le diagnostic clinique","contenu":"<p>Le diagnostic de <span class=\"kw-etio\">cystite aiguë gravidique</span> repose, comme chez la femme non enceinte, sur l'association de <strong>signes fonctionnels urinaires bas isolés</strong> (sans <span class=\"kw-clinique\">fièvre</span>, sans douleur lombaire) — mais quelques particularités cliniques chez la femme enceinte sont à connaître.</p>\n\n      <h4>Tableau clinique classique</h4>\n\n      <ul>\n        <li><span class=\"kw-clinique\">Brûlures mictionnelles</span> (signe le plus constant)</li>\n        <li><span class=\"kw-clinique\">Pollakiurie</span> (à interpréter avec prudence chez la femme enceinte, cf. ci-dessous)</li>\n        <li><span class=\"kw-clinique\">Impériosités mictionnelles</span></li>\n        <li><span class=\"kw-clinique\">Douleurs sus-pubiennes</span></li>\n        <li><span class=\"kw-clinique\">Hématurie macroscopique</span> possible (<span class=\"kw-etio\">cystite</span> hématurique)</li>\n        <li><strong>Apyrexie</strong>, <strong>pas de douleur lombaire</strong> (cf. critères qui font passer en PNA)</li>\n      </ul>\n\n      <h4>Particularités chez la femme enceinte</h4>\n\n      <table >\n        <thead>\n          <tr><th>Aspect</th><th>Particularité gravidique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Pollakiurie</span></strong></td>\n            <td>Moins discriminante car <span class=\"kw-clinique\">physiologique</span> au cours de la <span class=\"kw-ci\">grossesse</span> (compression vésicale par l'utérus gravide)</td>\n          </tr>\n          <tr>\n            <td><strong>Douleur lombaire</strong></td>\n            <td>Peut être présente en cas de <span class=\"kw-clinique\">contractions utérines</span> associées — attention au piège diagnostique avec une PNA débutante</td>\n          </tr>\n          <tr>\n            <td><strong>Contractions utérines</strong></td>\n            <td>Possibles dans la <span class=\"kw-etio\">cystite</span> aiguë gravidique — justifient une vigilance obstétricale</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège diagnostique.</strong> Toute <span class=\"kw-clinique\">fièvre</span> ou douleur lombaire associée fait sortir du cadre de la <span class=\"kw-etio\">cystite</span> et impose la recherche d'une <span class=\"kw-alerte\">PNA gravidique</span> (cf. <em>obj-8</em>) — il n'y a pas de « <span class=\"kw-etio\">cystite</span> fébrile » chez la femme enceinte.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-def\">Infection urinaire</span> · 26 — Douleur abdo aiguë chez femme enceinte</em></p>","frequence":0},{"id":"28-7","rang":"A","rubrique":"Diagnostic biologique","titre":"Cystite aiguë gravidique : connaître le diagnostic biologique","contenu":"<p>Le diagnostic <span class=\"kw-ttt\">biologique</span> repose sur l'<span class=\"kw-bio\">ECBU systématique</span> chez toute femme enceinte suspecte de <span class=\"kw-etio\">cystite</span> — à la différence de la <span class=\"kw-etio\">cystite</span> simple chez la femme non enceinte, où l'<span class=\"kw-bio\">ECBU</span> n'est pas systématique.</p>\n\n      <h4>Examens biologiques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Place</th><th>Critères</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Bandelette urinaire</span> (<span class=\"kw-bio\">BU</span>)</strong></td>\n            <td>Test de débrouillage</td>\n            <td>\n              Positive si <span class=\"kw-bio\">leucocytes</span> et/ou <span class=\"kw-bio\">nitrites</span><br>\n              Sensibilité &lt; <span class=\"kw-chiffre\">100 %</span> → <strong>pas de <span class=\"kw-bio\">BU</span> négative qui exclut le diagnostic</strong> en cas de symptômes\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">ECBU</span></strong></td>\n            <td><strong>Systématique</strong> chez la femme enceinte</td>\n            <td>\n              <strong><span class=\"kw-bio\">Leucocyturie</span></strong> ≥ <span class=\"kw-chiffre\">10⁴/mL</span><br>\n              <strong>Bactériurie</strong> significative selon le germe :<br>\n              — <span class=\"kw-chiffre\">≥ 10³ UFC/mL</span> pour <em><span class=\"kw-etio\">E. coli</span></em> et <em>S. saprophyticus</em><br>\n              — <span class=\"kw-chiffre\">≥ 10⁴ UFC/mL</span> pour les autres entérobactéries et entérocoques<br>\n              <strong>Antibiogramme</strong> systématique\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pourquoi l'<span class=\"kw-bio\">ECBU</span> est systématique.</strong> Chez la femme enceinte, le <span class=\"kw-alerte\">risque maternofœtal</span> (bascule en PNA, MAP, accouchement prématuré) impose de documenter le germe et son profil de sensibilité, à la fois pour adapter l'<span class=\"kw-ttt\">antibiothérapie</span> probabiliste secondairement (cf. <em>obj-7</em>) et pour repérer un <em>Proteus</em> (risque lithiasique) ou un SGB (prophylaxie per-partum).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-def\">Infection urinaire</span></em></p>","frequence":0},{"id":"28-8","rang":"A","rubrique":"Prise en charge","titre":"Cystite aiguë gravidique : connaître le traitement","contenu":"<p>La <span class=\"kw-etio\">cystite</span> aiguë gravidique impose une <strong><span class=\"kw-ttt\">antibiothérapie</span> probabiliste précoce</strong> dès le prélèvement <span class=\"kw-bio\">ECBU</span>, sans attendre l'<span class=\"kw-bio\">antibiogramme</span> — à la différence de la colonisation. La justification est le <span class=\"kw-alerte\">risque maternofœtal</span> (PNA, MAP).</p>\n\n      <h4>Étape 1 — <span class=\"kw-ttt\">Antibiothérapie</span> probabiliste (à débuter immédiatement)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Ordre</th><th>Molécule</th><th>Posologie</th><th>Durée</th><th>CI / EI</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td><span class=\"kw-ttt\">Fosfomycine-trométamol</span> (Monuril®)</td>\n            <td><span class=\"kw-chiffre\">3 g</span></td>\n            <td><span class=\"kw-chiffre\">Prise unique</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>2ᵉ intention</strong></td>\n            <td><span class=\"kw-ttt\">Pivmécillinam</span></td>\n            <td><span class=\"kw-chiffre\">400 mg</span> × 2 / j</td>\n            <td><span class=\"kw-chiffre\">7 jours</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>3ᵉ intention</strong></td>\n            <td><span class=\"kw-ttt\">Nitrofurantoïne</span></td>\n            <td><span class=\"kw-chiffre\">100 mg</span> × 3 / j</td>\n            <td><span class=\"kw-chiffre\">7 jours</span></td>\n            <td>\n              <span class=\"kw-ci\">CI :</span> traitements itératifs ; <span class=\"kw-bio\">clairance</span> &lt; <span class=\"kw-chiffre\">40 mL</span>/min ;<br>\n              <span class=\"kw-alerte\">risque pulmonaire et hépatique</span> si durée &gt; <span class=\"kw-chiffre\">10 jours</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Étape 2 — <span class=\"kw-ttt\">Antibiothérapie</span> adaptée à l'<span class=\"kw-bio\">antibiogramme</span></h4>\n\n      <p>L'efficacité des molécules est similaire ; les choix sont hiérarchisés sur la tolérance digestive et le risque de résistance secondaire :</p>\n\n      <ol>\n        <li><strong>1ʳᵉ intention :</strong> <span class=\"kw-ttt\">Amoxicilline</span> <span class=\"kw-chiffre\">1 g</span> ×<span class=\"kw-chiffre\"> 3/j</span> pendant <span class=\"kw-chiffre\">7 j</span> (si souche sensible — privilégier car peu impactante écologiquement)</li>\n        <li><strong>2ᵉ intention :</strong> <span class=\"kw-ttt\">Pivmécillinam</span> <span class=\"kw-chiffre\">400 mg</span> ×<span class=\"kw-chiffre\"> 2/j</span> pendant <span class=\"kw-chiffre\">7 j</span> <em>ou</em> <span class=\"kw-ttt\">Fosfomycine-trométamol</span> <span class=\"kw-chiffre\">3 g</span> en prise unique</li>\n        <li><strong>3ᵉ intention :</strong> <span class=\"kw-ttt\">Triméthoprime</span> <span class=\"kw-chiffre\">300 mg</span>/j × <span class=\"kw-chiffre\">7 j</span> (<span class=\"kw-ci\">à éviter pendant les 2 premiers mois de grossesse</span>)</li>\n        <li><strong>4ᵉ intention :</strong> <span class=\"kw-ttt\">Nitrofurantoïne</span> (mêmes CI que ci-dessus)</li>\n        <li><strong>Recours :</strong> <span class=\"kw-ttt\">cotrimoxazole</span>, <span class=\"kw-ttt\">amoxicilline</span> + acide clavulanique, <span class=\"kw-ttt\">céfixime</span>, <span class=\"kw-ttt\">ciprofloxacine</span> (<span class=\"kw-ci\">FQ à éviter</span>)</li>\n      </ol>\n\n      <h4><span class=\"kw-def\">Suivi</span> et mesures associées</h4>\n\n      <ul>\n        <li><strong><span class=\"kw-bio\">ECBU</span> de contrôle</strong> : <span class=\"kw-chiffre\">8 – 10 jours après l'arrêt</span> du traitement</li>\n        <li><strong><span class=\"kw-bio\">ECBU</span> mensuel</strong> jusqu'à la fin de la <span class=\"kw-ci\">grossesse</span></li>\n        <li><strong>Si SGB isolé</strong> dans un <span class=\"kw-bio\">ECBU</span> pendant la <span class=\"kw-ci\">grossesse</span> → <span class=\"kw-ttt\">antibioprophylaxie per-partum</span> (même protocole que pour le portage vaginal)</li>\n        <li><strong><span class=\"kw-ttt\">RHD</span> :</strong> boissons abondantes (<span class=\"kw-chiffre\">2 L</span>/j), mictions fréquentes et post-coïtales, hygiène périnéale d'avant en arrière</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Repère mnémotechnique.</strong> Probabiliste de la <span class=\"kw-etio\">cystite</span> gravidique = <strong>Fosfo &gt; Pivméc &gt; Nitro</strong>. Adaptée = <strong>Amox &gt; Pivméc/Fosfo &gt; Triméthoprime &gt; Nitro</strong>. L'<span class=\"kw-ttt\">amoxicilline</span> n'est jamais probabiliste (résistance d'<em><span class=\"kw-etio\">E. coli</span></em> trop élevée) mais redevient la 1ʳᵉ intention dès que la souche est démontrée sensible sur <span class=\"kw-bio\">antibiogramme</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-def\">Infection urinaire</span> · 177 — Anti-<span class=\"kw-etio\">infectieux</span> · 24 — Complications de la <span class=\"kw-ci\">grossesse</span></em></p>","frequence":1},{"id":"28-9","rang":"A","rubrique":"Diagnostic clinique","titre":"Pyélonéphrite aiguë gravidique : connaître le diagnostic clinique","contenu":"<p>La <span class=\"kw-etio\">pyélonéphrite aiguë (PNA) gravidique</span> complique <span class=\"kw-chiffre\">0,5 – 1 %</span> des grossesses (jusqu'à <span class=\"kw-chiffre\">2 %</span> dans certaines séries) et constitue la <strong>1ʳᵉ cause de <span class=\"kw-clinique\">fièvre</span> chez la femme enceinte</strong>. Les <span class=\"kw-def\">critères diagnostiques</span> sont identiques à ceux de la femme non enceinte, mais la symptomatologie est <span class=\"kw-alerte\">souvent trompeuse</span>.</p>\n\n      <h4>Tableau « classique » — Triade</h4>\n\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span> (souvent &gt; <span class=\"kw-chiffre\">38 °C</span>, parfois avec <span class=\"kw-clinique\">frissons</span>)</li>\n        <li><span class=\"kw-clinique\">Douleur lombaire</span> uni- ou bilatérale, irradiant vers la fosse iliaque ipsilatérale</li>\n        <li><span class=\"kw-clinique\">Signes fonctionnels urinaires</span> (brûlures, <span class=\"kw-clinique\">pollakiurie</span>, impériosités) — souvent au second plan</li>\n      </ul>\n\n      <h4>Particularités diagnostiques chez la femme enceinte</h4>\n\n      <table >\n        <thead>\n          <tr><th>Aspect</th><th>Particularité gravidique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Latéralité</strong></td>\n            <td>Plus souvent à droite qu'à gauche (compression de l'uretère droit par l'utérus gravide en <span class=\"kw-clinique\">dextroposition</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Présentation trompeuse</strong></td>\n            <td>\n              <strong>Début progressif</strong> sur quelques jours<br>\n              <strong>Signes peu intenses :</strong> simple fébricule, endolorissement lombaire modéré, vagues brûlures mictionnelles<br>\n              <strong><span class=\"kw-clinique\">Fièvre</span> isolée</strong>, souvent intermittente<br>\n              <strong><span class=\"kw-clinique\">Hématurie</span> fébrile</strong>, urines troubles<br>\n              <strong>Aspects pseudo-chirurgicaux :</strong> pseudo-appendiculaire, pseudo-cholécystique, pseudo-colitique (surtout si signes digestifs associés)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Recherche de <span class=\"kw-alerte\">signes de gravité</span></h4>\n\n      <ul>\n        <li><span class=\"kw-alerte\">Sepsis / choc septique</span> (<span class=\"kw-clinique\">hypotension</span>, marbrures, troubles de conscience)</li>\n        <li><span class=\"kw-alerte\">PNA hyperalgique</span> non soulagée par les <span class=\"kw-ttt\">antalgiques</span> de palier 1</li>\n        <li><span class=\"kw-alerte\">Doute sur un obstacle urétéral</span> (lithiase, dilatation au-delà de la dilatation physiologique gravidique)</li>\n        <li>Signes obstétricaux associés : contractions utérines, métrorragies, suspicion de <span class=\"kw-alerte\">rupture</span> prématurée des membranes</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Conséquence pratique.</strong> Toute <span class=\"kw-clinique\">fièvre</span> chez la femme enceinte impose la recherche d'une PNA — c'est l'<span class=\"kw-alerte\">étiologie la plus fréquente</span>. Le seuil de prescription d'un <span class=\"kw-bio\">ECBU</span> est très bas, et l'<span class=\"kw-alerte\">hospitalisation</span> est la règle (cf. <em>obj-10</em>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-def\">Infection urinaire</span> · 26 — Douleur abdo aiguë chez femme enceinte · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":1},{"id":"28-10","rang":"A","rubrique":"Diagnostic biologique","titre":"Pyélonéphrite aiguë gravidique : connaître le diagnostic biologique","contenu":"<p>Le bilan <span class=\"kw-ttt\">biologique</span> d'une PNA gravidique est <strong>plus large</strong> que celui d'une PNA hors <span class=\"kw-ci\">grossesse</span> : il documente l'infection, recherche un retentissement, dépiste un risque obstétrical, et anticipe une éventuelle prise en charge en <span class=\"kw-alerte\">réanimation</span>.</p>\n\n      <h4>Bilan <span class=\"kw-ttt\">biologique</span> obligatoire</h4>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>But</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">ECBU</span></strong></td>\n            <td>Documentation microbiologique + <span class=\"kw-bio\">antibiogramme</span> — <strong>systématique</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">NFS + CRP</span></strong></td>\n            <td><span class=\"kw-def\">Syndrome inflammatoire</span> : hyperleucocytose à PNN, <span class=\"kw-bio\">CRP</span> élevée</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Ionogramme + créatininémie</span></strong></td>\n            <td>Retentissement rénal, <span class=\"kw-clinique\">déshydratation</span>, dyskaliémie</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Glycémie</span></strong></td>\n            <td>Recherche d'un <span class=\"kw-def\">diabète</span> déséquilibré (FR + facteur aggravant)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-bio\">Hémocultures</span> — Indications</h4>\n\n      <p>Réalisation de <strong>3 <span class=\"kw-bio\">hémocultures</span></strong>, avec <span class=\"kw-bio\">recherche spécifique de <em>Listeria monocytogenes</em></span> si <span class=\"kw-bio\">BU</span> faiblement positive, dans les situations suivantes :</p>\n\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre &gt; 38 °C</span> ou <span class=\"kw-clinique\">frissons</span></li>\n        <li><span class=\"kw-alerte\">Signes de gravité</span> (<span class=\"kw-etio\">sepsis</span>, <span class=\"kw-alerte\">choc</span>, <span class=\"kw-clinique\">hypotension</span>, troubles de conscience)</li>\n        <li><span class=\"kw-clinique\">Doute diagnostique</span> (tableau atypique, présentation trompeuse pseudo-chirurgicale)</li>\n      </ul>\n\n      <h4>Imagerie associée — <span class=\"kw-imagerie\">Échographie</span> des voies urinaires</h4>\n\n      <p>L'<span class=\"kw-imagerie\">échographie des voies urinaires avec doppler des jets urétéraux</span> est la seule imagerie envisagée en routine chez la femme enceinte. Indications en <span class=\"kw-alerte\">urgence (&lt; 24 h)</span> :</p>\n\n      <ul>\n        <li><span class=\"kw-alerte\">PNA hyperalgique</span></li>\n        <li><span class=\"kw-alerte\">Doute avec obstacle urétéral</span> — à interpréter en tenant compte de la <span class=\"kw-chiffre\">dilatation pyélocalicielle physiologique</span> au cours de la <span class=\"kw-ci\">grossesse</span></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Pourquoi rechercher <em>Listeria</em>.</strong> La listériose materno-fœtale peut mimer une PNA fébrile et entraîne des complications obstétricales graves (chorioamniotite, fausse couche tardive, infection néonatale, mort fœtale). Une <span class=\"kw-bio\">BU</span> faiblement positive doit en faire évoquer le diagnostic et faire prescrire des <span class=\"kw-bio\">hémocultures</span> dédiées.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-def\">Infection urinaire</span> · 173 — Zoonose · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"28-11","rang":"B","rubrique":"Prise en charge","titre":"Pyélonéphrite aiguë gravidique : connaître le traitement","contenu":"<p>La PNA gravidique impose une <strong><span class=\"kw-alerte\">hospitalisation</span> initiale</strong>, une <strong><span class=\"kw-ttt\">antibiothérapie</span> probabiliste IV</strong> et une <strong><span class=\"kw-def\">surveillance</span> obstétricale</strong> rapprochée. Les fluoroquinolones sont <span class=\"kw-ci\">contre-indiquées</span>.</p>\n\n      <h4>Orientation — <span class=\"kw-alerte\">Hospitalisation</span> initiale recommandée</h4>\n\n      <p>Un relais ambulatoire est secondairement envisageable si <strong>tous les critères suivants sont réunis</strong> :</p>\n\n      <ul>\n        <li>Bonne tolérance clinique</li>\n        <li>PNA non hyperalgique</li>\n        <li>Absence de <span class=\"kw-clinique\">vomissements</span></li>\n        <li>Examen obstétrical normal</li>\n        <li>Contexte permettant une <span class=\"kw-def\">surveillance</span> à domicile par des proches</li>\n        <li>Absence d'immunodépression, d'ATCD d'IU récidivantes et d'uropathie connue</li>\n      </ul>\n\n      <h4><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste — En l'absence de <span class=\"kw-alerte\">signes de gravité</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Ordre</th><th>Molécule</th><th>Posologie</th><th>Commentaires</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td><span class=\"kw-ttt\">C3G IV : céfotaxime ou ceftriaxone</span></td>\n            <td>Céfotaxime <span class=\"kw-chiffre\">1 à 2 g</span> / <span class=\"kw-chiffre\">8 h</span> · Ceftriaxone <span class=\"kw-chiffre\">1 g</span> / <span class=\"kw-chiffre\">24 h</span></td>\n            <td>Efficace sur la plupart des entérobactéries communautaires · excellente tolérance</td>\n          </tr>\n          <tr>\n            <td><strong>Si <span class=\"kw-ci\">allergie</span> aux C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span></strong></td>\n            <td><span class=\"kw-ttt\">Aztréonam</span></td>\n            <td><span class=\"kw-chiffre\">1 g</span> / <span class=\"kw-chiffre\">12 h</span></td>\n            <td>Uniquement en milieu hospitalier</td>\n          </tr>\n          <tr>\n            <td>—</td>\n            <td><span class=\"kw-ttt\">Ciprofloxacine</span></td>\n            <td><span class=\"kw-chiffre\">500 mg</span> × 2 / j</td>\n            <td><span class=\"kw-ci\">À éviter si traitement par quinolones &lt; 6 mois</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste — En présence de <span class=\"kw-alerte\">signes de gravité</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Ordre</th><th>Molécule</th><th>Posologie</th><th>Commentaires</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td><span class=\"kw-ttt\">C3G IV (céfotaxime ou ceftriaxone) + amikacine</span></td>\n            <td>Céfotaxime <span class=\"kw-chiffre\">1 à 2 g</span> / <span class=\"kw-chiffre\">8 h</span> · Ceftriaxone <span class=\"kw-chiffre\">1 g</span> / <span class=\"kw-chiffre\">24 h</span> + <strong>amikacine <span class=\"kw-chiffre\">15 mg</span>/kg / <span class=\"kw-chiffre\">24 h</span></strong></td>\n            <td>L'amikacine est rapidement bactéricide, efficace sur les entérobactéries (y compris EBLSE ≈ <span class=\"kw-chiffre\">90 %</span>) · synergie avec les C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> · <strong>durée <span class=\"kw-chiffre\">1 à 3 jours</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Si <span class=\"kw-ci\">allergie</span> aux C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span></strong></td>\n            <td><span class=\"kw-ttt\">Aztréonam + amikacine</span></td>\n            <td>Aztréonam <span class=\"kw-chiffre\">2 g</span> / <span class=\"kw-chiffre\">8 h</span> + amikacine <span class=\"kw-chiffre\">15 mg</span>/kg / <span class=\"kw-chiffre\">24 h</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Si risque d'EBLSE</strong></td>\n            <td><span class=\"kw-ttt\">Imipénem + amikacine</span></td>\n            <td>Imipénem <span class=\"kw-chiffre\">500 mg</span> / <span class=\"kw-chiffre\">6 h</span> + amikacine <span class=\"kw-chiffre\">15 mg</span>/kg / <span class=\"kw-chiffre\">24 h</span></td>\n            <td>ATCD d'<span class=\"kw-bio\">ECBU</span> à EBLSE &lt; <span class=\"kw-chiffre\">6 mois</span> ; <em>ou</em> <span class=\"kw-etio\">choc septique</span> + <span class=\"kw-chiffre\">≥ 1</span> FDR d'EBLSE</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Relais et durée</h4>\n\n      <ol>\n        <li><strong>Relais à <span class=\"kw-chiffre\">48 h</span></strong> selon <span class=\"kw-bio\">antibiogramme</span> — schéma identique aux autres PNA, en privilégiant l'<span class=\"kw-ttt\">amoxicilline</span> si la souche est sensible (meilleure tolérance)</li>\n        <li><strong>Durée totale</strong> : <span class=\"kw-chiffre\">≥ 14 jours</span> (souvent <span class=\"kw-chiffre\">2 à 4 semaines</span>)</li>\n        <li><span class=\"kw-ci\">Fluoroquinolones contre-indiquées</span> pendant la <span class=\"kw-ci\">grossesse</span> (sauf situation exceptionnelle après concertation)</li>\n      </ol>\n\n      <h4>Mesures associées</h4>\n\n      <ul>\n        <li><strong><span class=\"kw-def\">Surveillance</span> obstétricale :</strong> enregistrement tococardiographique fœtal à partir de <span class=\"kw-chiffre\">25 SA</span>, évaluation du col utérin, élimination d'une <span class=\"kw-alerte\">rupture</span> prématurée des membranes (en cas de doute clinique ou <span class=\"kw-ttt\">biologique</span>)</li>\n        <li><strong>Hydratation maternelle</strong><span class=\"kw-chiffre\"> 2 L</span>/<span class=\"kw-chiffre\">24 h</span> (en l'absence d'obstacle)</li>\n        <li><strong><span class=\"kw-ttt\">Paracétamol</span></strong> <span class=\"kw-chiffre\">1 g</span> toutes les <span class=\"kw-chiffre\">6 h</span> (<span class=\"kw-ttt\">antalgique</span> + antipyrétique)</li>\n        <li><strong>Tocolytique + <span class=\"kw-ttt\">corticothérapie</span> anténatale</strong> si risque d'accouchement prématuré</li>\n      </ul>\n\n      <h4>Échec de l'<span class=\"kw-ttt\">antibiothérapie</span></h4>\n\n      <div class=\"callout callout-warn\">\n        <strong>Persistance de douleurs ou de <span class=\"kw-clinique\">fièvre</span> sous ATB adaptée.</strong> Évoquer un <span class=\"kw-alerte\">obstacle</span> nécessitant un <span class=\"kw-ttt\">drainage</span> en <span class=\"kw-alerte\">urgence</span> — notamment en cas d'infection à <em><span class=\"kw-etio\">Proteus mirabilis</span></em> (lithiase phospho-ammoniaco-magnésienne).\n      </div>\n\n      <h4><span class=\"kw-def\">Suivi</span> post-traitement</h4>\n\n      <ul>\n        <li><span class=\"kw-bio\">ECBU</span> de <span class=\"kw-def\">surveillance</span> : <span class=\"kw-chiffre\">8 – 10 jours après l'arrêt</span> du traitement</li>\n        <li><span class=\"kw-bio\">ECBU</span> mensuel jusqu'à la fin de la <span class=\"kw-ci\">grossesse</span></li>\n        <li><span class=\"kw-ttt\">Antibioprophylaxie per-partum</span> si SGB isolé dans un <span class=\"kw-bio\">ECBU</span> pendant la <span class=\"kw-ci\">grossesse</span></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-def\">Infection urinaire</span> · 177 — Anti-<span class=\"kw-etio\">infectieux</span> · 332 — Etat de <span class=\"kw-alerte\">choc</span> · 24 — Complications de la <span class=\"kw-ci\">grossesse</span></em></p>","frequence":1},{"id":"28-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications et non indications des examens d’imagerie dans les infections urinaires au cours de la grossesse","contenu":"<p>L'imagerie a une <strong>place réduite</strong> dans la prise en charge des IU gravidiques : la <span class=\"kw-ci\">grossesse</span> impose d'éviter les rayonnements ionisants quand l'examen n'apportera pas un bénéfice diagnostique décisif. L'<span class=\"kw-imagerie\">échographie</span> reste la modalité de référence.</p>\n\n      <h4><span class=\"kw-imagerie\">Échographie</span> des voies urinaires — Indications</h4>\n\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Indication</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>PNA hyperalgique</strong></td>\n            <td><span class=\"kw-imagerie\">Échographie + doppler des jets urétéraux</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">&lt; 24 h</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Doute sur un obstacle urétéral</strong> (lithiase suspectée, dilatation importante)</td>\n            <td><span class=\"kw-imagerie\">Échographie + doppler des jets urétéraux</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">&lt; 24 h</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span> défavorable</strong> sous ATB adaptée</td>\n            <td><span class=\"kw-imagerie\">Échographie</span> à la recherche d'un obstacle, d'une lithiase ou d'un <span class=\"kw-clinique\">abcès</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Non-indications</h4>\n\n      <ul>\n        <li><strong><span class=\"kw-etio\">Cystite</span> aiguë gravidique non compliquée</strong> : pas d'imagerie systématique</li>\n        <li><strong>Colonisation urinaire gravidique</strong> : pas d'imagerie</li>\n        <li><strong>PNA gravidique simple, sans <span class=\"kw-alerte\">signe de gravité</span> ni doute d'obstacle</strong> : l'<span class=\"kw-imagerie\">échographie</span> n'est pas obligatoire si l'<span class=\"kw-clinique\">évolution</span> clinique est rapidement favorable</li>\n      </ul>\n\n      <h4>Pièges et précautions liés à l'imagerie gravidique</h4>\n\n      <div class=\"callout callout-warn\">\n        <strong>Dilatation pyélocalicielle physiologique.</strong> Une <span class=\"kw-radio\">dilatation modérée des cavités pyélocalicielles</span> est habituelle au cours de la <span class=\"kw-ci\">grossesse</span> (compression et hypotonie urétérales), plus marquée à droite. L'interprétation d'une dilatation à l'<span class=\"kw-imagerie\">échographie</span> doit en tenir compte avant de conclure à un obstacle pathologique.\n      </div>\n\n      <h4>Examens irradiants</h4>\n\n      <ul>\n        <li><strong><span class=\"kw-radio\">TDM (uro-scanner)</span> :</strong> <span class=\"kw-ci\">à éviter</span> en routine ; à discuter au cas par cas en concertation pluridisciplinaire si l'<span class=\"kw-imagerie\">échographie</span> est non concluante et que le bénéfice diagnostique l'emporte</li>\n        <li><strong><span class=\"kw-radio\">ASP, UIV</span> :</strong> non recommandés pendant la <span class=\"kw-ci\">grossesse</span></li>\n        <li><strong><span class=\"kw-radio\">IRM</span> :</strong> envisageable en seconde intention en cas de doute persistant (non irradiante), sans injection de gadolinium au 1ᵉʳ trimestre</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-def\">Infection urinaire</span> · 24 — Complications de la <span class=\"kw-ci\">grossesse</span> · 26 — Douleur abdo aiguë chez femme enceinte</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>PNA gravidique avec <span class=\"kw-alerte\">signes de gravité</span> <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> infectieuse</span></strong></p><p><span class=\"kw-ttt\">C3G IV + amikacine</span> immédiat ; <span class=\"kw-alerte\">réanimation</span> si <span class=\"kw-alerte\">choc septique</span></p><ul><li><span class=\"kw-alerte\">Sepsis / choc septique</span> (<span class=\"kw-clinique\">hypotension</span>, marbrures, troubles de conscience) → prise en charge immédiate</li><li><span class=\"kw-alerte\">PNA hyperalgique</span> non soulagée par les <span class=\"kw-ttt\">antalgiques</span> de palier 1</li><li><span class=\"kw-alerte\">Doute sur un obstacle urétéral</span> → <span class=\"kw-imagerie\">échographie + doppler des jets urétéraux</span> en <span class=\"kw-alerte\">urgence</span> <span class=\"kw-chiffre\">&lt; 24 h</span></li></ul><p><strong>Obstacle urétéral sur PNA <span class=\"q\">— <span class=\"kw-ttt\">drainage</span> en <span class=\"kw-alerte\">urgence</span></span></strong></p><p><span class=\"kw-ttt\">drainage de l'obstacle</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li>Persistance de <span class=\"kw-clinique\">douleurs</span> ou <span class=\"kw-clinique\">hyperthermie</span> sous ATB adaptée → évoquer un obstacle</li><li><span class=\"kw-def\">Terrain</span> à risque : <span class=\"kw-etio\">Proteus mirabilis</span> → <span class=\"kw-alerte\">lithiase phospho-ammoniaco-magnésienne</span></li></ul>","hospit":"<p><strong>Colonisation urinaire gravidique</strong></p><ul><li>Traitement <strong>ambulatoire</strong> — pas d'<span class=\"kw-alerte\">hospitalisation</span></li><li><span class=\"kw-ci\">Pas d'antibiothérapie probabiliste</span> : attendre l'<span class=\"kw-bio\">ECBU</span> + <span class=\"kw-bio\">antibiogramme</span></li></ul><p><strong>Cystite aiguë gravidique</strong></p><ul><li>Traitement <strong>ambulatoire</strong> possible</li><li><span class=\"kw-ttt\">Antibiothérapie probabiliste immédiate</span> dès prélèvement <span class=\"kw-bio\">ECBU</span></li></ul><p><strong>PNA gravidique <span class=\"q\">— <span class=\"kw-alerte\">hospitalisation</span> initiale systématique</span></strong></p><ul><li><strong><span class=\"kw-alerte\">Hospitalisation</span> initiale</strong> recommandée dans tous les cas</li><li>Relais ambulatoire secondairement envisageable si <strong>tous</strong> les <span class=\"kw-chiffre\">6 critères</span> réunis :</li><li>① bonne tolérance clinique · ② <span class=\"kw-clinique\">PNA non hyperalgique</span> · ③ absence de <span class=\"kw-clinique\">vomissements</span></li><li>④ examen obstétrical normal · ⑤ <span class=\"kw-def\">surveillance</span> à domicile possible · ⑥ absence d'immunodépression / <span class=\"kw-etio\">uropathie</span> connue / <span class=\"kw-etio\">ATCD d'IU récidivantes</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Sepsis / choc septique</span> : <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">marbrures</span>, troubles de conscience</li><li><span class=\"kw-alerte\">PNA hyperalgique</span> non soulagée par les <span class=\"kw-ttt\">antalgiques</span> de palier 1</li><li><span class=\"kw-alerte\">Obstacle urétéral</span> suspecté (non-amélioration sous ATB, <span class=\"kw-etio\">Proteus mirabilis</span>)</li><li>Signes obstétricaux associés : <span class=\"kw-alerte\">contractions utérines</span>, <span class=\"kw-alerte\">métrorragies</span>, suspicion de <span class=\"kw-alerte\">rupture prématurée des membranes</span></li><li><span class=\"kw-alerte\">Fièvre ≥ 38 °C + frissons</span> chez la femme enceinte → évoquer PNA en priorité (1ʳᵉ cause de <span class=\"kw-clinique\">fièvre</span> gravidique)</li></ul>","principes":"<p><strong>3 entités distinctes</strong> — <span class=\"kw-def\">colonisation gravidique</span> (asymptomatique), <span class=\"kw-def\">cystite gravidique</span> (symptômes bas, apyrétique), <span class=\"kw-def\">PNA gravidique</span> (<span class=\"kw-clinique\">fièvre</span> + douleur lombaire) — avec une stratégie <span class=\"kw-ttt\">ATB</span> différenciée. <span class=\"kw-ci\">Fluoroquinolones contre-indiquées</span> pendant toute la <span class=\"kw-ci\">grossesse</span>.</p><p><strong>Colonisation urinaire gravidique</strong></p><ul><li><span class=\"kw-ci\">Pas de traitement probabiliste</span> — <span class=\"kw-ttt\">antibiothérapie</span> adaptée à l'<span class=\"kw-bio\">antibiogramme</span> uniquement</li><li>1ʳᵉ intention : <span class=\"kw-ttt\">amoxicilline</span> · 2ᵉ : <span class=\"kw-ttt\">pivmécillinam</span> · 3ᵉ : <span class=\"kw-ttt\">fosfomycine-trométamol</span> prise unique</li><li>Durée <span class=\"kw-chiffre\">7 jours</span> (sauf fosfomycine prise unique)</li></ul><p><strong>Cystite aiguë gravidique</strong></p><ul><li><strong><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste immédiate</strong> dès prélèvement de l'<span class=\"kw-bio\">ECBU</span></li><li>Probabiliste : <span class=\"kw-ttt\">fosfomycine-trométamol</span> prise unique &gt; <span class=\"kw-ttt\">pivmécillinam</span> <span class=\"kw-chiffre\">7 j</span> &gt; <span class=\"kw-ttt\">nitrofurantoïne</span> <span class=\"kw-chiffre\">7 j</span></li><li>Adaptée : <span class=\"kw-ttt\">amoxicilline</span> (1ʳᵉ si sensible) · puis <span class=\"kw-ttt\">pivmécillinam</span> / <span class=\"kw-ttt\">fosfomycine</span> · <span class=\"kw-ttt\">triméthoprime</span> (<span class=\"kw-ci\">éviter T1</span>) · <span class=\"kw-ttt\">nitrofurantoïne</span></li></ul><p><strong>PNA gravidique sans <span class=\"kw-alerte\">signes de gravité</span></strong></p><ul><li>Probabiliste : <span class=\"kw-ttt\">C3G IV</span> (<span class=\"kw-ttt\">céfotaxime</span> <span class=\"kw-chiffre\">1-2 g / 8 h</span> ou <span class=\"kw-ttt\">ceftriaxone</span> <span class=\"kw-chiffre\">1 g / 24 h</span>)</li><li><span class=\"kw-ci\">Allergie</span> C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> : <span class=\"kw-ttt\">aztréonam</span></li><li>Relais à <span class=\"kw-chiffre\">48 h</span> selon <span class=\"kw-bio\">antibiogramme</span> · durée totale <span class=\"kw-chiffre\">≥ 14 jours</span></li></ul><p><strong>PNA gravidique avec <span class=\"kw-alerte\">signes de gravité</span> / risque EBLSE</strong></p><p><span class=\"kw-ci\">Fluoroquinolones contre-indiquées</span> pendant la <span class=\"kw-ci\">grossesse</span></p><ul><li>1ʳᵉ intention : <span class=\"kw-ttt\">C3G IV + amikacine</span> <span class=\"kw-chiffre\">15 mg/kg / 24 h</span> (durée amikacine <span class=\"kw-chiffre\">1-3 jours</span>)</li><li><span class=\"kw-ci\">Allergie</span> C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> : <span class=\"kw-ttt\">aztréonam + amikacine</span></li><li>Risque EBLSE (<span class=\"kw-bio\">ECBU</span> à EBLSE <span class=\"kw-chiffre\">&lt; 6 mois</span> ou <span class=\"kw-alerte\">choc</span> + <span class=\"kw-chiffre\">≥ 1</span> FDR) : <span class=\"kw-ttt\">imipénem + amikacine</span></li></ul>","suivi":"<p><strong><span class=\"kw-bio\">ECBU</span> de contrôle systématique</strong> : <span class=\"kw-chiffre\">8-10 jours après l'arrêt</span> du traitement (colonisation, cystite, PNA), puis <span class=\"kw-bio\">ECBU</span> mensuel jusqu'à l'accouchement.<br><strong><span class=\"kw-def\">Surveillance</span> obstétricale PNA :</strong> enregistrement tococardiographique fœtal à partir de <span class=\"kw-chiffre\">25 SA</span> · évaluation du col · élimination d'une <span class=\"kw-alerte\">RPM</span>.<br><strong>SGB dans un <span class=\"kw-bio\">ECBU</span> :</strong> → <span class=\"kw-ttt\">antibioprophylaxie per-partum</span> systématique (même protocole que portage vaginal).</p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-11-item-161-infections-urinaires-de-ladulte-et-de-lenfant/","label":"Collège AFU — Infections urinaires (chap. 11, item 161)"},{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-161.pdf","label":"Collège Pilly — Infections urinaires 2023 (item 161, PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Femme enceinte — bactériurie suspectée ou dépistée — BU positive ou ECBU demandé — préciser : symptômes ? fièvre ? douleur lombaire ?","detail":"<h4>CAT — infection urinaire chez la femme enceinte — Démarche diagnostique : 3 entités (colonisation / cystite / PNA) — stratégie ATB différenciée</h4>","branches":[{"to":"q-asympto","label":"Asymptomatique (BU/ECBU positif fortuit)","color":"blue"},{"to":"q-sympto","label":"Symptomatique (SFU présents)","color":"amber"}]},{"id":"q-asympto","kind":"decision","label":"ECBU confirme bactériurie ≥ 10⁵ UFC/mL (× 2) ? — 2 ECBU positifs successifs à la même bactérie, patiente sans SFU ni fièvre","branches":[{"to":"t-colonisation","label":"Oui — 2 ECBU positifs","color":"amber"},{"to":"t-pas-colonisation","label":"Non (BU faux-positif ou ECBU < seuil)","color":"green"}]},{"id":"t-colonisation","kind":"terminal","label":"Colonisation urinaire gravidique","color":"amber","detail":"<h4>Définition</h4><ul><li><span class=\"kw-def\">Colonisation gravidique</span> = bactériurie ≥ <span class=\"kw-chiffre\">10⁵ UFC/mL</span> × 2 <span class=\"kw-bio\">ECBU</span>, <strong>asymptomatique</strong></li></ul><h4>ATB</h4><ul><li><span class=\"kw-ci\">Pas de traitement probabiliste</span> — attendre <span class=\"kw-bio\">antibiogramme</span></li><li>1ʳᵉ intention : <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">7 j</span></li><li>2ᵉ : <span class=\"kw-ttt\">pivmécillinam</span> <span class=\"kw-chiffre\">7 j</span> · 3ᵉ : <span class=\"kw-ttt\">fosfomycine-trométamol</span> prise unique</li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li><span class=\"kw-bio\">ECBU</span> contrôle <span class=\"kw-chiffre\">8-10 j après arrêt</span> puis mensuel jusqu'à accouchement</li></ul><h4>Alerte</h4><ul><li>Si <span class=\"kw-etio\">SGB</span> isolé → <span class=\"kw-ttt\">antibioprophylaxie per-partum</span></li></ul>"},{"id":"t-pas-colonisation","kind":"terminal","label":"Pas de colonisation — surveillance seule","color":"green","detail":"<h4>CAT</h4><ul><li>Poursuite du <span class=\"kw-def\">dépistage</span> mensuel par <span class=\"kw-bio\">BU</span> / <span class=\"kw-bio\">ECBU</span> selon le profil de risque</li></ul>"},{"id":"q-sympto","kind":"decision","label":"Fièvre > 38 °C et/ou douleur lombaire ? — Discriminer cystite (bas appareil, apyrétique) vs PNA (haut appareil, fébrile)","branches":[{"to":"t-cystite","label":"Non — SFU isolés, apyrétique, pas de douleur lombaire","color":"amber"},{"to":"q-gravite-pna","label":"Oui — fièvre et/ou douleur lombaire","color":"red"}]},{"id":"t-cystite","kind":"terminal","label":"Cystite aiguë gravidique","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Brûlures mictionnelles</span> + <span class=\"kw-clinique\">pollakiurie</span> + <span class=\"kw-clinique\">impériosités</span></li><li>Apyrétique, sans douleur lombaire</li><li><span class=\"kw-bio\">ECBU systématique</span> chez la femme enceinte (à la différence de la cystite simple)</li></ul><h4>ATB probabiliste immédiate</h4><ul><li>1ʳᵉ intention : <span class=\"kw-ttt\">fosfomycine-trométamol</span> <span class=\"kw-chiffre\">3 g</span> prise unique</li><li>2ᵉ : <span class=\"kw-ttt\">pivmécillinam</span> <span class=\"kw-chiffre\">400 mg × 2 / j</span> pendant <span class=\"kw-chiffre\">7 j</span></li><li>3ᵉ : <span class=\"kw-ttt\">nitrofurantoïne</span> <span class=\"kw-chiffre\">100 mg × 3 / j</span> pendant <span class=\"kw-chiffre\">7 j</span></li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li><span class=\"kw-bio\">ECBU</span> contrôle <span class=\"kw-chiffre\">8-10 j après arrêt</span> puis mensuel</li></ul><h4>Renvoi</h4><ul><li>Item 161 (Infection urinaire de l'adulte)</li></ul>"},{"id":"q-gravite-pna","kind":"decision","label":"Signes de gravité ? — Sepsis/choc · PNA hyperalgique · obstacle urétéral · signes obstétricaux","branches":[{"to":"t-pna-simple","label":"Non — PNA bien tolérée, examen obstétrical normal","color":"amber"},{"to":"t-pna-grave","label":"Oui — signes de gravité ou risque EBLSE","color":"red"}]},{"id":"t-pna-simple","kind":"terminal","label":"PNA gravidique sans signe de gravité","color":"amber","detail":"<h4>Orientation</h4><ul><li><strong><span class=\"kw-alerte\">Hospitalisation</span> initiale</strong> + relais ambulatoire envisageable si <span class=\"kw-chiffre\">6 critères</span> réunis</li></ul><h4>ATB probabiliste</h4><ul><li>1ʳᵉ intention : <span class=\"kw-ttt\">C3G IV</span> — <span class=\"kw-ttt\">céfotaxime</span> <span class=\"kw-chiffre\">1-2 g / 8 h</span> ou <span class=\"kw-ttt\">ceftriaxone</span> <span class=\"kw-chiffre\">1 g / 24 h</span></li><li><span class=\"kw-ci\">Allergie</span> C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> : <span class=\"kw-ttt\">aztréonam</span> <span class=\"kw-chiffre\">1 g / 12 h</span></li></ul><h4>Relais & durée</h4><ul><li>Relais à <span class=\"kw-chiffre\">48 h</span> selon <span class=\"kw-bio\">antibiogramme</span> (privilégier <span class=\"kw-ttt\">amoxicilline</span> si sensible) · durée totale <span class=\"kw-chiffre\">≥ 14 jours</span></li></ul><h4>Mesures associées</h4><ul><li>Enregistrement tococardiographique fœtal à partir de <span class=\"kw-chiffre\">25 SA</span></li><li><span class=\"kw-ttt\">Paracétamol</span> <span class=\"kw-chiffre\">1 g / 6 h</span> <span class=\"kw-ttt\">antalgique</span> + antipyrétique</li><li>Hydratation <span class=\"kw-chiffre\">2 L / 24 h</span></li></ul><h4>Renvoi</h4><ul><li>Item 161 (Infection urinaire) · Item 26 (Douleur abdominale chez femme enceinte)</li></ul>"},{"id":"t-pna-grave","kind":"terminal","label":"PNA gravidique avec signes de gravité / risque EBLSE","color":"red","detail":"<h4>Orientation</h4><ul><li><span class=\"kw-alerte\">Hospitalisation immédiate</span> — <span class=\"kw-alerte\">réanimation</span> si <span class=\"kw-alerte\">choc septique</span></li></ul><h4>ATB probabiliste</h4><ul><li>1ʳᵉ intention : <span class=\"kw-ttt\">C3G IV + amikacine</span> <span class=\"kw-chiffre\">15 mg/kg / 24 h</span> (durée amikacine <span class=\"kw-chiffre\">1-3 j</span>)</li><li><span class=\"kw-ci\">Allergie</span> C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> : <span class=\"kw-ttt\">aztréonam + amikacine</span></li><li>Risque EBLSE (<span class=\"kw-bio\">ECBU</span> à EBLSE <span class=\"kw-chiffre\">&lt; 6 mois</span> ou <span class=\"kw-alerte\">choc</span> + <span class=\"kw-chiffre\">≥ 1</span> FDR) : <span class=\"kw-ttt\">imipénem + amikacine</span></li></ul><h4>Imagerie urgente</h4><ul><li><span class=\"kw-imagerie\">Échographie + doppler des jets urétéraux</span> en <span class=\"kw-alerte\">urgence</span> <span class=\"kw-chiffre\">&lt; 24 h</span> (PNA hyperalgique ou doute obstacle)</li></ul><h4><span class=\"kw-ci\">Contre-indication</span></h4><ul><li><span class=\"kw-ci\">Fluoroquinolones contre-indiquées</span> pendant la <span class=\"kw-ci\">grossesse</span></li></ul>"}]},"cards":[]};